private static function roundValue(float $number, int $digits, bool $roundUp): float
{
    $sign = $number < 0.0 ? -1 : 1;
    $number = abs($number);
    $scientific = sprintf('%.' . (PHP_FLOAT_DIG - 1) . 'e', $number);
    [$mantissa, $exponent] = explode('e', strtolower($scientific));
    $exponent = (int) $exponent;
    $digitString = str_replace('.', '', $mantissa);
    $length = strlen($digitString);
    $cutoff = $exponent + 1 + $digits;

    if ($cutoff <= 0) {
        return $roundUp ? $sign * 10.0 ** -$digits : 0.0;
    }

    if ($cutoff >= $length) {
        return $sign * (float) ($digitString . 'e' . ($exponent - $length + 1));
    }

    $kept = substr($digitString, 0, $cutoff);
    if ($roundUp && trim(substr($digitString, $cutoff), '0') !== '') {
        $kept = self::incrementDecimalString($kept);
    }

    return $sign * (float) ($kept . 'e' . (-$digits));
}

private static function incrementDecimalString(string $digits): string
{
    $index = strlen($digits) - 1;
    while ($index >= 0) {
        if ($digits[$index] !== '9') {
            $digits[$index] = chr(ord($digits[$index]) + 1);

            return $digits;
        }
        $digits[$index] = '0';
        --$index;
    }

    return '1' . $digits;
}

